const SVC_CATS = {
  bar: { icon: '\ud83c\udf7a', label: 'Bars and pubs', note: 'Bars, pubs and beer gardens within reach of the road, kept apart from the eating list because they answer a different question - this is where a ride ends, not where you stop for lunch. Opening hours are only shown where OpenStreetMap records them.' },
  stay: { icon: '\ud83d\udecf\ufe0f', label: 'Beds', note: 'Hotels, guest houses, hostels and mountain huts near the route. A hut is filed here rather than under food: it is the thing you cannot get at a restaurant, and the eating list reaches in for the ones that also feed you. Book ahead in season - mountain beds go early, and hours are never invented.' },
  fuel: { icon: '⛽', label: 'Fuel', note: 'Brands, opening hours and 24/7 flags from OpenStreetMap. Per-litre prices are not published in open data, so the roadbook does not invent them - it flags the forecourts most likely to be cheaper and says why: a supermarket forecourt, an independent, a chain that usually undercuts, or several stations competing within a kilometre. Motorway forecourts are marked down because they are reliably dearer. Check the sign; these are odds, not prices.' },
  moto: { icon: '🏍️', label: 'Bike service', note: 'Dealers and repair shops within reach of the route. Worth a phone call before you rely on one on a Sunday.' },
  camera: { icon: '📷', label: 'Speed cameras', note: 'Fixed cameras mapped in OpenStreetMap, shown for route planning. Using a device or app to warn you about cameras while riding is illegal in Switzerland, Germany and France, among others - read this before you leave, not on the move. Mapped cameras are also incomplete, and mobile controls appear anywhere. Ride the posted limit.' },
  police: { icon: '🚓', label: 'Police & help', note: 'Police stations and hospitals near the route. Emergency number 112 works across the EU, Switzerland and the UK.' },
  food: { icon: '🍽️', label: 'Food & coffee', note: 'Near your planned stops. Opening hours come from OpenStreetMap and can be out of date - in the mountains, assume kitchens close mid-afternoon.' },
  view: { icon: '🌄', label: 'Viewpoints', note: 'Mapped viewpoints and picnic spots close to the road, with the named summits you can pick out from each one. Park legally: a blocked passing place is how riders lose access to good roads.' },
  rest: { icon: '☕', label: 'Rest & refresh', note: 'Places to get off the bike: rest areas, picnic spots, drinking water, toilets and shelter. On a long day the stops matter as much as the road - concentration goes before your arms do.' },
  swim: { icon: '🏊', label: 'Swim spots', note: 'Lake and river bathing places within reach of the route. Cold alpine water plus a hot ride is a shock to the system - get in slowly, and never dive into water you have not seen the bottom of.' },
};
function classifySvc(t) {
  if (!t) return null;
  if (t.amenity === 'fuel' || t.amenity === 'charging_station') return 'fuel';
  if (t.shop === 'motorcycle' || t.shop === 'motorcycle_repair' || t.shop === 'motorcycle_parts' ||
      t.craft === 'motorcycle_repair' || (t.shop === 'car_repair' && /motorcycle|motorrad|moto/i.test(t.name || ''))) return 'moto';
  if (t.highway === 'rest_area' || t.highway === 'services' || t.amenity === 'drinking_water' ||
      t.amenity === 'shelter' || t.tourism === 'picnic_site' || t.leisure === 'picnic_table' ||
      (t.amenity === 'toilets' && t.access !== 'private')) return 'rest';
  if (t.highway === 'speed_camera' || t.enforcement === 'maxspeed') return 'camera';
  if (t.amenity === 'police' || t.amenity === 'hospital') return 'police';
  /* A BED IS A BED, EVEN IF IT FEEDS YOU. This test sat BELOW the food test, so a hotel
     with a restaurant, and every mountain hut, was filed as somewhere to eat and the
     accommodation bucket stayed empty. The classifier returns on first match. */
  /* A HOTEL IS A BED - BUT A HUT IS NOT, AND I HAVE NOW LEARNED THAT TWICE.
     tools/test-stops.mjs carries the note from the last attempt: moving huts to 'stay'
     takes them out of every roadbook stop group, because that surface is built from the
     food/view/swim/moto/fuel kinds. I did it again anyway and the roadbook went to zero
     groups. Hotels, guest houses, hostels, motels and chalets - unambiguously beds, and
     never classified at all until today - go to 'stay'. A hut stays FOOD, and the
     accommodation list reaches in for it, which is the arrangement that already worked. */
  if (/^(hotel|guest_house|hostel|motel|apartment)$/.test(t.tourism || '')) return 'stay';
  /* A BAR IS NOT A RESTAURANT. He asked for both, and they answer different questions: one
     is lunch, the other is where the ride ends. Folded together, a rider looking for dinner
     got a list of pubs. */
  /* A BAR IS SHOWN SEPARATELY BUT NOT TAKEN OUT OF THE EATING LIST: a Gasthaus feeds
     people, and removing food from the page to tidy a taxonomy is the wrong trade. The
     bar CARD filters the food bucket instead of owning these outright. */
  /* EVERYTHING THAT FEEDS A RIDER, including the pubs and the huts. Bars are SHOWN as
     their own card by filtering this bucket, not by being removed from it: a place can
     answer two questions, and taking food off the page to tidy a category is the wrong
     trade. The hut belongs here for the same reason - on a pass road the hut IS lunch. */
  if (t.amenity === 'restaurant' || t.amenity === 'cafe' || t.amenity === 'fast_food' ||
      t.amenity === 'biergarten' || t.amenity === 'pub' || t.amenity === 'bar' ||
      t.amenity === 'ice_cream' ||
      t.tourism === 'alpine_hut' || t.tourism === 'wilderness_hut') return 'food';
  /* A supermarket next to a forecourt is the single best cheap-fuel signal in open data,
     so it has to survive classification instead of being discarded as "not a service". */
  if (t.shop === 'supermarket' || t.shop === 'convenience') return 'shop';
  /* conditions - surface, works, and the places traffic backs up */
  if (t.highway === 'construction' || t.construction) return 'works';
  if (t.mountain_pass === 'yes') return 'pass';
  if (t.enforcement || t.highway === 'speed_camera' || t.type === 'enforcement' ||
      (t['man_made'] === 'surveillance' &&
       (/camera|ALPR/i.test(t['surveillance:type'] || '') || t['surveillance:zone'] === 'traffic')))
    return 'camera';
  /* a 30 zone is not a hazard, it is a place you will lose your licence if you treat it
     like the road either side of it */
  if (/^(20|30)$/.test(t.maxspeed || '') || /[:]30$/.test(t['zone:maxspeed'] || '') ||
      t.traffic_calming) return 'slow';
  if (t.barrier === 'border_control') return 'border';
  if (t.amenity === 'ferry_terminal' || t.route === 'ferry') return 'ferry';
  if (t.highway === 'rest_area' || t.highway === 'services') return 'rest';
  if (t.winter_road === 'yes' || t.seasonal === 'yes') return 'hazard';
  if (t.surface && /cobblestone|sett|gravel|unpaved|compacted|ground|dirt|sand|pebblestone/.test(t.surface)) return 'rough';
  if (t.smoothness && /bad|horrible|impassable/.test(t.smoothness)) return 'rough';
  if (t.tunnel === 'yes' && t.name) return 'queue';
  if (t.barrier === 'toll_booth' || t.toll === 'yes') return 'toll';
  if (t.ford === 'yes') return 'hazard';
  if (t.hazard) return 'hazard';
  if (/^(gate|lift_gate|block|bollard)$/.test(t.barrier || '')) return 'hazard';
  if (t.maxweight || (t.width && parseFloat(t.width) <= 2.5)) return 'hazard';
  if (t.tourism === 'viewpoint' || (t.natural === 'peak' && t.ele)) return 'view';
  if (t.historic || t.tourism === 'attraction' || t.tourism === 'museum' ||
      t.tourism === 'artwork' || t.waterway === 'waterfall' ||
      /^(waterfall|cave_entrance|arch|cliff)$/.test(t.natural || '')) return 'sight';
  if (t.leisure === 'swimming_area' || t.natural === 'beach' || t.amenity === 'public_bath' ||
      (t.sport === 'swimming' && t.leisure !== 'sports_centre')) return 'swim';
  return null;
}
function svcName(t, cat) {
  return t.name || t.brand || t.operator ||
    (cat === 'camera' ? 'Speed camera' : cat === 'fuel' ? 'Fuel station' :
     cat === 'police' ? (t.amenity === 'hospital' ? 'Hospital' : 'Police station') :
     cat === 'rest' ? (t.highway === 'rest_area' ? 'Rest area' : t.highway === 'services' ? 'Services' :
                       t.amenity === 'drinking_water' ? 'Drinking water' : t.amenity === 'toilets' ? 'Toilets' :
                       t.amenity === 'shelter' ? 'Shelter' : 'Picnic spot') : 'Unnamed');
}
/* SPLIT THE ASK, OR ONE SLOW CLAUSE EMPTIES THE PAGE.
   This grew from about twelve clauses to thirty-two as features were added, all in a single
   request. Overpass answers a heavy query with a timeout, and a single failure meant
   "service scan unavailable" and an empty Worth-stopping-for - which is exactly what he
   reported after earlier editions had been full. Three smaller requests, run one after the
   other, and whatever comes back is kept. Only if ALL of them fail is anything said. */
/* ---- A VERSIONED, DATED JURISDICTION POLICY ----
   Not a regex buried in a render function. Each entry says what the mode is, what it rests
   on, when it was checked and when it must be looked at again - so a stale rule is visible
   rather than assumed still true. `prohibited` means the data is never requested at all.
   `suppress` means it may be fetched but is not shown as navigation guidance. */
/* Changed by hand, in the same commit as the policy text it dates. Never new Date(). */
/* ---- ONLY HTTPS, ONLY HOSTS WE ACTUALLY USE ----
   Every picture the app shows comes from Wikimedia. Anything else in a url field is either a
   mistake or an attack, and neither belongs in a style attribute or an img src. */
const PHOTO_HOSTS = /^(upload\.wikimedia\.org|commons\.wikimedia\.org|[a-z0-9-]+\.wikimedia\.org)$/i;
function safePhotoUrl(u) {
  try {
    /* ---- A PROTOCOL-RELATIVE URL IS NOT A LOCAL FILE ----
       "//upload.wikimedia.org/..." resolved against location.href, which on the portable
       build downloaded to a Downloads folder is file: - so the guard rejected genuine
       Wikimedia pictures and the checkpoint photos vanished from the roadbook. Resolve
       those against https, which is what the browser does with them on a served page. */
    const raw = String(u || '').trim();
    if (!raw) return false;
    const url = new URL(raw.startsWith('//') ? 'https:' + raw : raw,
                        /^https?:/i.test(location.href) ? location.href : 'https://curvescout.com/');
    return url.protocol === 'https:' && PHOTO_HOSTS.test(url.hostname);
  } catch (e) { return false; }
}

/* a protocol-relative url needs the scheme put back before it is used as a src */
function photoSrc(u) {
  const raw = String(u || '').trim();
  return raw.startsWith('//') ? 'https:' + raw : raw;
}

