  secs.forEach(sc => {
    const i = idxOf(sc.from), j = idxOf(sc.to);
    if (i < 0 || j < 0 || j <= i) return;
    out.push({ from: cum[i] / total, to: cum[j] / total, type: sc.type,
               label: sc.from + ' → ' + sc.to, km: sc.km });
  });
